// generar_278_franjas_en_rutina_alimentacion.js
// CHIQUI Entre Señales — Franjas (mañana/tarde/noche) en la rutina de
// Alimentación
//
// Ya registrábamos en qué momento del día se alimenta (☀️/🌤️/🌙),
// pero ese dato no aparecía en ningún análisis. Ahora la rutina de
// "Alimentación" en Rutinas de cuidado (Análisis) muestra la
// distribución sobre todo el historial:
//
//   ¿En qué momento suele comer?
//   ☀️ Mañana  ████████░░  85%
//   🌤️ Tarde   ██░░░░░░░░  20%
//   🌙 Noche   ██████░░░░  60%
//
// Se calcula sobre los días en que se marcó "Alimenté" y que tienen
// franja registrada. Como un día puede tener varias franjas, los
// porcentajes son proporciones independientes (pueden sumar más de
// 100) — cada barra responde "de los días que comió, en cuántos fue
// en este momento".
//
// Utilidad: sobre todo para cotutores ("¿en casa le dan de comer en la
// mañana o en la noche?"), pero también para ver hábitos alimentarios.
//
// Técnico: se agrega alimento_franjas al query de rutinas (una columna
// más, liviano) y un cálculo que solo corre para la fila de
// alimentación. El resto del catálogo no se toca.
//
// No hay SQL (la columna alimento_franjas ya existe desde el 275).
//
// Uso:
//   node generar_278_franjas_en_rutina_alimentacion.js

const fs2 = require('fs')
const path = require('path')

const archivos = [
  {
    ruta: 'app/analisis/page.tsx',
    base64: ""
  },
]

let errores = 0
for (const a of archivos) {
  try {
    const rutaCompleta = path.join(process.cwd(), a.ruta)
    fs2.mkdirSync(path.dirname(rutaCompleta), { recursive: true })
    const contenido = Buffer.from(a.base64, 'base64').toString('utf8')
    fs2.writeFileSync(rutaCompleta, contenido, 'utf8')
    console.log('OK: ' + a.ruta)
  } catch (e) {
    errores++
    console.error('ERROR escribiendo ' + a.ruta + ': ' + e.message)
  }
}

if (errores === 0) {
  console.log('\nListo. 1 archivo escrito. git add / commit / push.')
} else {
  console.error('\nTerminó con ' + errores + ' error(es). NO hagas push.')
  process.exit(1)
}
